"""Speaking Part 2 — build part2-turn.json (v3).

Content words are written inside [[double brackets]]. The build removes the
brackets for the spoken text and turns each one into ___ for the pattern, so
the pattern can never drift from the answer.

Long turn: 50–60 s. Partner question: 20–30 s. Both at 2.5 words a second.
"""
import json, re, sys

def S(m, t, marks=(), wrong=()):
    s = {"m": m, "t": t}
    if marks: s["marks"] = list(marks)
    if wrong: s["wrong"] = [{"t": a, "why": b} for a, b in wrong]
    return s
def T(why, *segs): return {"why": why, "segs": list(segs)}

# ── why a wrong option is wrong ──
DESCRIBE = "Pure description. The examiner can see the photo — say what you think is going on, and why."
PREF     = "That's your own preference. Save it for the partner's question — the minute is about the people in the photos."
NOCOMP   = "This talks about one photo on its own. Link it to the other: 'on the other hand', 'whereas', 'by contrast'."
TOOSURE  = "Too certain. You can't know from a photo — 'might', 'probably', 'I imagine' keep it honest."
ENDING   = "A stock ending that says nothing. Sum up with one idea that joins both photos."
OFFQ     = "It forgets the printed question. Every part of the minute should answer it."
LONGCMP  = "A second round of comparing. One sentence is enough — then answer the question."
FORMAL   = "Correct English, but it sounds like an essay. Speak like yourself."
STOCK    = "The examiner hears this fifty times a day. React to the question instead."
FLAT     = "Flat. Show how you feel about the question."
SAME     = "That's the answer again. This move has to add something new."
VAGUE    = "Vague. An example is one moment you could film — a day, a place, a person."
NOTURN   = "No turn. A contrast has to swing back the other way."
GEN      = "About people in general, not about you."

TASKS = []
def task(id_, tab, q, fu, p1, p2, alts):
    TASKS.append({"id": id_, "tab": tab, "question": q, "followUp": fu,
                  "photos": [{"title": p1[0], "brief": p1[1]}, {"title": p2[0], "brief": p2[1]}],
                  "alts": alts})

