def secs_words(t): return len([w for w in t.split() if re.search(r'[A-Za-z0-9]', w)])
def secs(t): return round(secs_words(t)/2.5)
def clean(t): return re.sub(r'\[\[(.*?)\]\]', r'\1', t)
def blank(t): return re.sub(r'\[\[(.*?)\]\]', '___', t)

bad = 0
for tk in TASKS:
    assert len(tk["alts"]) == 3, tk["id"]
    for i, alt in enumerate(tk["alts"]):
        for part, lo, hi, order in (("turn", 50, 60, "kpqs"), ("partner", 20, 30, None)):
            blk = alt[part]
            blk["frame"] = ("\n" if part == "turn" else " ").join(blank(s["t"]) for s in blk["segs"])
            for s in blk["segs"]:
                s["t"] = clean(s["t"])
                for m in s.get("marks", []):
                    if m not in s["t"]: print("MARK", tk["id"], i, part, m); bad += 1
                if s["m"] not in ("k", "a") and len(s.get("wrong", [])) < 2:
                    print("WRONG", tk["id"], i, part, s["m"]); bad += 1
                if re.search(r"\bhere\b.*\bhere\b", s["t"]): print("HERE", tk["id"], i); bad += 1
            ms = "".join(s["m"] for s in blk["segs"]); tot = sum(secs(s["t"]) for s in blk["segs"])
            ok = lo <= tot <= hi and "___" in blk["frame"]
            if order: ok = ok and ms == order
            else: ok = ok and "a" in ms and len(set(ms)) == len(ms) and ("x" not in ms or ms[0] == "x") and len(ms) < 5
            print(f"{'  ' if ok else '!!'} {tk['id']:12} {['Default','Alt 1','Alt 2'][i]:8} {part:8} {ms:5} {tot}s")
            bad += not ok

